import { useEffect, useState, useContext } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import AuthContext from '../context/AuthContext'; // 👈 Add this

export default function QuizList() {
  const [quizzes, setQuizzes] = useState([]);
  const { user, logout } = useContext(AuthContext); // 👈 Get user + logout
  const navigate = useNavigate();

  useEffect(() => {
    axios.get('http://localhost:5000/api/quizzes')
      .then(res => setQuizzes(res.data));
  }, []);

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  // 🔍 Debug: Log user role to console
  useEffect(() => {
    console.log('Current user:', user);
  }, [user]);

  return (
    <div className="p-6">
      {/* 👇 User Info & Controls */}
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-2xl">Welcome, {user?.name}!</h1>
          <span className={`inline-block mt-1 px-2 py-0.5 text-xs rounded ${
            user?.role === 'admin' 
              ? 'bg-red-100 text-red-800' 
              : 'bg-blue-100 text-blue-800'
          }`}>
            {user?.role}
          </span>
        </div>
        
        <div className="space-x-3">
          {/* 👇 Show Admin Dashboard link only for admins */}
          {user?.role === 'admin' && (
            <button
              onClick={() => navigate('/admin')}
              className="bg-purple-600 text-white px-3 py-1 rounded text-sm hover:bg-purple-700"
            >
              Admin Dashboard
            </button>
          )}
          
          <button
            onClick={handleLogout}
            className="bg-red-600 text-white px-3 py-1 rounded text-sm hover:bg-red-700"
          >
            Logout
          </button>
        </div>
      </div>

      {/* 👇 Quiz List */}
      <h2 className="text-xl font-bold mb-4">Available Quizzes</h2>
      {quizzes.length === 0 ? (
        <p className="text-gray-500">No quizzes available.</p>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {quizzes.map(q => (
            <div key={q._id} className="border p-4 rounded">
              <h3 className="font-bold">{q.title}</h3>
              <p>Subject: {q.subject}</p>
              <p>Time: {Math.floor(q.timeLimit / 60)} mins | {q.difficulty}</p>
              <button
                onClick={() => navigate(`/quiz/${q._id}`)}
                className="mt-2 bg-green-600 text-white px-3 py-1 rounded hover:bg-green-700"
              >
                Start Quiz
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
